### 8. Create server-side ShipmentService implementation

Create `/tmp/sv-34108af768e44481af962993f8b73f73/ShipmentTracker/ShipmentTracker/Services/ShipmentServiceServer.cs`:

```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServiceServer : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServiceServer(ApplicationDbContext db)
    {
        _db = db;
    }

    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await _db.Shipments
            .OrderByDescending(s => s.CreatedDate)
            .Select(s => s.ToModel())
            .ToListAsync();
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await _db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity?.ToModel();
    }

    public async Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await _db.Shipments
            .Where(s => s.CustomerEmail == customerEmail)
            .OrderByDescending(s => s.CreatedDate)
            .Select(s => s.ToModel())
            .ToListAsync();
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        shipment.TrackingNumber = GenerateTrackingNumber();
        shipment.CreatedDate = DateTime.UtcNow;
        shipment.Status = ShipmentStatus.Pending;

        var entity = ShipmentEntity.FromModel(shipment);
        _db.Shipments.Add(entity);
        await _db.SaveChangesAsync();
        return entity.ToModel();
    }

    public async Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await _db.Shipments.FindAsync(id)
            ?? throw new InvalidOperationException("Shipment not found");
        entity.Status = status;
        await _db.SaveChangesAsync();
        return entity.ToModel();
    }

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpper()}";
    }
}
```

### 9. Create API endpoints

Create `/tmp/sv-34108af768e44481af962993f8b73f73/ShipmentTracker/ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:

```csharp
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        });

        group.MapGet("customer/{customerEmail}", async (string customerEmail, IShipmentService service) =>
            Results.Ok(await service.GetShipmentsByCustomerAsync(customerEmail)));

        group.MapPost("", async (Shipment shipment, IShipmentService service) =>
            Results.Created($"api/shipments/track/{shipment.TrackingNumber}", await service.CreateShipmentAsync(shipment)));

        group.MapPut("{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
            Results.Ok(await service.UpdateShipmentStatusAsync(id, status)));
    }
}
```

